using System;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.IO;using System.Linq;using System.Text;using System.Windows.Forms;
namespace BeamScheduleFormatter {
/* Base Plate & Anchor Bolts design sheet (owner, 19 November 2026: "Design ng baseplate tapos anchor bolt") */
class BasePlateForm:DesignSheetForm {
 static readonly CultureInfo Inv=CultureInfo.InvariantCulture;
 readonly TextBox reactions=new TextBox{Multiline=true,ScrollBars=ScrollBars.Both,WordWrap=false,Width=1000,Height=260,Tag="FullWidth",Font=new Font("Consolas",9),MaxLength=0};
 readonly Label loaded=new Label{Width=1000,Height=60,Tag="FullWidth",ForeColor=PowTheme.Muted};readonly DataGridView results=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};
 public BasePlateForm():base("Base Plate & Anchor Bolts | AISC Design Guide 1, NSCP 2015 Section 417","Base-Plate"){
  var loads=Section("STAAD reactions","Paste the STAAD Support Reactions table of the column bases (node, L/C, Fx, Fy, Fz, Mx, My, Mz) for the factored (LRFD) combinations, or type the rows. Positive vertical reaction = compression on the plate.");
  Choice(loads,"Vertical","Vertical axis",new[]{"Y","Z"});Choice(loads,"MomentAxis","Moment bending the plate along N",new[]{"Mz","Mx","My"});NumberField(loads,"Nodes","Column base nodes to design (blank = all)","");
  var act=new FlowLayoutPanel{Width=1000,Height=46,Tag="FullWidth"};Action<string,Action> button=(text,action)=>{var b=new Button{Text=text,AutoSize=true,Height=32};b.Click+=(s,e)=>{try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,text);}};act.Controls.Add(b);};
  button("Paste Support Reactions table",()=>{if(!Clipboard.ContainsText())throw new Exception("Copy the STAAD Support Reactions table first.");reactions.Text=Clipboard.GetText();});
  button("Import CSV / Excel",()=>{using(var d=new OpenFileDialog{Filter="STAAD tables|*.csv;*.tsv;*.txt;*.xlsx;*.xlsm|All files|*.*"})if(d.ShowDialog(this)==DialogResult.OK){string ext=Path.GetExtension(d.FileName).ToLowerInvariant();var texts=ext==".xlsx"||ext==".xlsm"?StaadSpreadsheet.Tables(d.FileName).Values.ToList():new List<string>{File.ReadAllText(d.FileName)};Exception last=null;foreach(var t in texts){try{string u;TrussSupport.Reactions(t,out u);reactions.Text=t;return;}catch(Exception ex){last=ex;}}throw new Exception("No Support Reactions table found. "+(last==null?"":last.Message));}});
  loads.Controls.Add(act);loads.Controls.Add(reactions);Inputs.Add("Reactions",reactions);loads.Controls.Add(loaded);
  var col=Section("Column and plate","Column on a base plate over an RC pedestal. m, n and λn' follow AISC Design Guide 1 for I / W, HSS rectangle and pipe columns.");
  Choice(col,"ColumnType","Column section",new[]{"I / W section","HSS rectangle","Pipe / round HSS"});NumberField(col,"ColumnD","Column depth d (or pipe diameter) (mm)","300");NumberField(col,"ColumnBf","Column flange width bf (mm)","200");NumberField(col,"ColumnTf","Column flange / wall thickness (mm)","12");
  NumberField(col,"B","Plate width B (mm)","400");NumberField(col,"N","Plate length N, along the moment (mm)","450");NumberField(col,"Tp","Plate thickness tp (mm)","25");NumberField(col,"Fy","Plate Fy (MPa)","248");
  NumberField(col,"PedestalB","Pedestal width (mm)","600");NumberField(col,"PedestalN","Pedestal length (mm)","650");NumberField(col,"PedestalDepth","Pedestal depth (mm)","600");NumberField(col,"Fc","Concrete fc' (MPa)","21");
  var anc=Section("Anchor bolts","Cast-in anchors in two rows, one near each end of the plate (along N); the row on the tension side resists the moment, all anchors resist uplift and shear. Condition B (no supplementary reinforcement).");
  Choice(anc,"AnchorSize","Anchor bolt (Powersteel A x B x C x D)",new[]{"Custom (enter the diameter and hef)"}.Concat(AnchorBolts.Powersteel.Select(a=>a.Name)).ToArray());Choice(anc,"BoltDia","Anchor diameter",AnchorBolts.DiameterLabels).SelectedItem="3/4 in (19.1 mm)";Choice(anc,"BoltsPerSide","Anchors in each row",new[]{"2","1","3","4"});NumberField(anc,"EdgeN","Anchor row from the plate end (mm)","50");NumberField(anc,"Gauge","Gauge of the outer anchors across B (mm)","250");NumberField(anc,"Hef","Embedment hef (mm)","400");
  Choice(anc,"AnchorType","Anchor type",new[]{"Headed (nut / head)","Hooked J or L bolt"});NumberField(anc,"HookEh","Hook length eh (mm, J/L bolt)","100");NumberField(anc,"Futa","Anchor futa (MPa)","400");NumberField(anc,"Fya","Anchor fya (MPa)","250");
  Toggle(anc,"Cracked","Cracked concrete (normal assumption)",true);Toggle(anc,"Grout","Grout pad under the plate (0.8 Vsa)",true);Toggle(anc,"Friction","Take friction 0.55 Pu on grout for shear",false);
  var page=new TabPage("Results");foreach(var h in new[]{"CHECK","CLAUSE","GOVERNING NODE","LOAD CASE","DEMAND","CAPACITY","RATIO","RESULT"})results.Columns.Add("c"+results.Columns.Count,h);page.Controls.Add(results);AddResultPage(page);
  foreach(var c in Inputs.Values){c.TextChanged+=(s,e)=>{if(!Restoring)Refresh0();};var combo=c as ComboBox;if(combo!=null)combo.SelectedIndexChanged+=(s,e)=>{if(!Restoring)Refresh0();};var box=c as CheckBox;if(box!=null)box.CheckedChanged+=(s,e)=>{if(!Restoring)Refresh0();};}
  /* a Powersteel size fills the diameter, hook and embedment (length less what projects above the concrete) */
  ((ComboBox)Inputs["AnchorSize"]).SelectedIndexChanged+=(s,e)=>{if(!Restoring)ApplyAnchorSize();};foreach(var key in new[]{"Tp"})Inputs[key].TextChanged+=(s,e)=>{if(!Restoring&&PowersteelSize()!=null)ApplyAnchorSize();};((CheckBox)Inputs["Grout"]).CheckedChanged+=(s,e)=>{if(!Restoring&&PowersteelSize()!=null)ApplyAnchorSize();};
  ((ComboBox)Inputs["AnchorSize"]).SelectedItem=AnchorBolts.Powersteel.First(a=>a.Name.StartsWith("Ø1\" x 24\"")).Name;
  Shown+=(s,e)=>Refresh0();}
 AnchorBolts.Size PowersteelSize(){return AnchorBolts.Powersteel.FirstOrDefault(a=>a.Name==Value("AnchorSize"));}
 void ApplyAnchorSize(){var a=PowersteelSize();if(a==null)return;double t;if(!double.TryParse(Value("Tp"),NumberStyles.Float,Inv,out t))return;double hef=a.LengthIn*25.4-AnchorBolts.Projection(a.DiaMm,t,((CheckBox)Inputs["Grout"]).Checked)-a.DiaMm;Restoring=true;try{((ComboBox)Inputs["BoltDia"]).SelectedItem=AnchorBolts.Label(a.DiaMm);Inputs["HookEh"].Text=(a.HookIn*25.4).ToString("0",Inv);Inputs["Hef"].Text=Math.Max(10,hef).ToString("0",Inv);((ComboBox)Inputs["AnchorType"]).SelectedIndex=1;}finally{Restoring=false;}Refresh0();}
 protected override bool OptionalSavedInput(string key){return key=="AnchorSize"||key=="Nodes";}
 internal List<SupportReaction> Rows(out string unit){var all=TrussSupport.Reactions(reactions.Text,out unit);var wanted=Value("Nodes").Split(new[]{',',' ',';'},StringSplitOptions.RemoveEmptyEntries).ToList();if(wanted.Count==0)return all;var list=all.Where(r=>wanted.Contains(r.Node.Split(' ')[0])).ToList();if(list.Count==0)throw new Exception("None of the nodes "+string.Join(", ",wanted)+" is in the reactions.");return list;}
 internal BasePlateInput Input(){Func<string,double> n=Number;return new BasePlateInput{ColumnType=Value("ColumnType"),ColumnD=n("ColumnD"),ColumnBf=n("ColumnBf"),ColumnTf=n("ColumnTf"),B=n("B"),N=n("N"),Tp=n("Tp"),Fy=n("Fy"),Fc=n("Fc"),PedestalB=n("PedestalB"),PedestalN=n("PedestalN"),PedestalDepth=n("PedestalDepth"),BoltDia=AnchorBolts.ParseDiameter(Value("BoltDia")),BoltName=PowersteelSize()==null?"":PowersteelSize().Name,ThreadLength=PowersteelSize()==null?0:PowersteelSize().ThreadIn*25.4,BoltsPerSide=int.Parse(Value("BoltsPerSide"),Inv),EdgeN=n("EdgeN"),Gauge=n("Gauge"),Hef=n("Hef"),Futa=n("Futa"),Fya=n("Fya"),HookEh=n("HookEh"),Headed=Value("AnchorType").StartsWith("Headed"),Cracked=((CheckBox)Inputs["Cracked"]).Checked,Grout=((CheckBox)Inputs["Grout"]).Checked,Friction=((CheckBox)Inputs["Friction"]).Checked,Vertical=Value("Vertical"),MomentAxis=Value("MomentAxis")};}
 void Refresh0(){results.Rows.Clear();if(reactions.Text.Trim()==""){loaded.Text="No reactions yet. Paste or import the STAAD Support Reactions table.";return;}
  try{string unit;var rows=Rows(out unit);var notes=new List<string>();var checks=BasePlate.Check(Input(),rows,notes,null);foreach(var c in checks){int i=results.Rows.Add(c.Name,c.Clause,c.Node,c.Case,TrussSupport.F(c.Demand,"0.00")+" "+c.Unit,TrussSupport.F(c.Capacity,"0.00")+" "+c.Unit,TrussSupport.F(c.Ratio,"0.00"),c.Ok?"OK":"NG");if(!c.Ok)results.Rows[i].DefaultCellStyle.ForeColor=Color.Firebrick;}
   int ng=checks.Count(c=>!c.Ok);loaded.ForeColor=ng>0?Color.Firebrick:PowTheme.Teal;loaded.Text=rows.Count+" reaction rows, "+rows.Select(r=>r.Node).Distinct().Count()+" node(s); unit "+unit+".\r\n"+(ng>0?ng+" check(s) NG - see Results.":"All checks pass - largest ratio "+TrussSupport.F(checks.Max(c=>c.Ratio),"0.00")+".");}
  catch(Exception ex){loaded.ForeColor=Color.Firebrick;loaded.Text=ex.Message;}}
 protected override void AfterRestore(){Refresh0();}
 protected override string BuildReport(){string unit;var rows=Rows(out unit);var input=Input();var notes=new List<string>();var detail=new List<BasePlateRow>();var checks=BasePlate.Check(input,rows,notes,detail);var b=new StringBuilder();
  b.AppendLine("COLUMN BASE PLATE AND ANCHOR BOLTS");b.AppendLine();b.AppendLine("## 01  DESIGN BASIS");b.AppendLine("LRFD: AISC Design Guide 1 (2nd ed.) and AISC 360-10 J8 (NSCP 2015 Chapter 5) for bearing and the plate; NSCP 2015 Section 417 (ACI 318-14 Chapter 17) for the anchors. STAAD factored reactions, unit "+unit+"; vertical axis "+input.Vertical+"; plate moment from "+input.MomentAxis+".");b.AppendLine();
  b.AppendLine("## 02  INPUTS");b.AppendLine("Column: "+input.ColumnType+", d = "+TrussSupport.F(input.ColumnD,"0")+" mm, bf = "+TrussSupport.F(input.ColumnBf,"0")+" mm; plate Fy "+TrussSupport.F(input.Fy,"0")+" MPa; fc' "+TrussSupport.F(input.Fc,"0.#")+" MPa; anchors "+(input.Headed?"headed":"hooked J/L")+", futa "+TrussSupport.F(input.Futa,"0")+" / fya "+TrussSupport.F(input.Fya,"0")+" MPa, hef "+TrussSupport.F(input.Hef,"0")+" mm, "+(input.Cracked?"cracked":"uncracked")+" concrete.");foreach(var n in notes)b.AppendLine(n);b.AppendLine();
  b.AppendLine("## 03  REACTIONS AND PLATE ACTION (kN, kN·m, mm)");b.AppendLine("Node      L/C                   Pu        Vu        Mu       e         Case              Y        Tu");foreach(var d in detail.Take(60))b.AppendLine(d.Reaction.Node.PadRight(10)+(d.Reaction.Case.Length>20?d.Reaction.Case.Substring(0,20):d.Reaction.Case).PadRight(22)+TrussSupport.F(d.Pu/1000,"0.00").PadLeft(8)+TrussSupport.F(d.Vu/1000,"0.00").PadLeft(10)+TrussSupport.F(d.Mu/1e6,"0.00").PadLeft(9)+(d.Pu>0?TrussSupport.F(d.E,"0"):"-").PadLeft(9)+"   "+(d.Uplift?"uplift":d.LargeMoment?"large moment":"small moment").PadRight(17)+(double.IsNaN(d.Y)||d.Uplift?"-":TrussSupport.F(d.Y,"0")).PadLeft(6)+TrussSupport.F(double.IsInfinity(d.Tu)?double.NaN:d.Tu/1000,"0.00").PadLeft(10));b.AppendLine();
  b.AppendLine("## 04  CHECKS (governing reaction row for each)");b.AppendLine("Check                          Clause              Node    L/C           Demand        Capacity      Ratio  Result");foreach(var c in checks)b.AppendLine(c.Name.PadRight(31)+c.Clause.PadRight(20)+c.Node.PadRight(8)+(c.Case.Length>12?c.Case.Substring(0,12):c.Case).PadRight(14)+(TrussSupport.F(c.Demand,"0.00")+" "+c.Unit).PadRight(14)+(TrussSupport.F(c.Capacity,"0.00")+" "+c.Unit).PadRight(14)+TrussSupport.F(c.Ratio,"0.00").PadRight(7)+(c.Ok?"OK":"NG")+"   "+c.Note);
  int ng=checks.Count(c=>!c.Ok);b.AppendLine();b.AppendLine(ng==0?"All checks satisfied for the reactions given.":ng+" check(s) not satisfied - revise the plate, pedestal or anchors.");b.AppendLine("Column-to-plate welds, anchor reinforcement and pedestal design are outside this sheet. Design calculation prepared with DTCE Tool Kit; it is not an engineer's approval.");return b.ToString();}
}
}
